@dataclass(frozen=True)
class OtpCodeSmsApi:
    """Local-only key holder that never serializes the full credential."""

    api_key: str | None = field(repr=False)

    @classmethod
    def from_environment(
        cls,
        environ: dict[str, str] | None = None,
        key_file: Path | None = None,
    ) -> "OtpCodeSmsApi":
        values = os.environ if environ is None else environ
        value = values.get(API_KEY_ENV, "").strip()
        if not value:
            secret_path = DEFAULT_KEY_FILE if key_file is None else key_file
            if secret_path.is_file():
                value = next(
                    (
                        line.strip()
                        for line in secret_path.read_text(encoding="utf-8").splitlines()
                        if line.strip() and not line.lstrip().startswith("#") and not line.strip().startswith("PASTE_")
                    ),
                    "",
                )
        return cls(api_key=value or None)

    @property
    def configured(self) -> bool:
        return self.api_key is not None

    @property
    def health_state(self) -> str:
        """Return only a truthful local configuration state; no network call occurs."""
        return "CONTRACT_UNVERIFIED" if self.configured else "NOT_CONFIGURED"

    @property
    def redacted_key(self) -> str:
        if self.api_key is None:
            return "NOT_CONFIGURED"
        return "CONFIGURED"

    def require_documented_contract(self) -> None:
        """Fail closed until the authenticated dashboard supplies an API contract."""
        if not self.configured:
            raise RuntimeError(f"{API_KEY_ENV} is not configured")
        raise RuntimeError("OTPCODESMS API contract has not been verified from the authenticated dashboard")

    def get_balance(self, transport: JsonTransport | None = None) -> int:
        payload = self._fetch("get_balance", {}, transport)
        if not isinstance(payload, Mapping) or "balance" not in payload:
            self._raise_failure("get_balance", payload)
        try:
            return int(payload["balance"])
        except (TypeError, ValueError) as exc:
            raise ProviderApiError("OTPCODESMS", "get_balance", OperationState.PROVIDER_ERROR) from exc

    def list_servers(self) -> tuple[OtpCodeSmsServer, ...]:
        """List the documented SIM pools as first-class server resources.

        The authenticated documentation exposes five independent SIM catalog
        actions, but no separate server-enumeration endpoint.  These records
        retain that provenance instead of inventing server IDs from a hidden
        parameter or from a service's inventory count.
        """
        return tuple(
            OtpCodeSmsServer(
                server_id=server_id,
                label=server_id.replace("_", " "),
                catalog_action=action,
                version=SIM_POOL_VERSION[server_id],
                capabilities=OtpCodeSmsServerCapabilities(
                    supports_service_specific_stock=server_id != "SIM_V1",
                ),
            )
            for server_id, action in SIM_POOL_ACTIONS.items()
        )

    def get_server(self, server_id: str) -> OtpCodeSmsServer | None:
        return next((server for server in self.list_servers() if server.server_id == server_id), None)

    def list_inventory(self, server: OtpCodeSmsServer, transport: JsonTransport | None = None) -> tuple[OtpCodeSmsInventory, ...]:
        """Read the live catalog for exactly one documented SIM server."""
        expected_action = SIM_POOL_ACTIONS.get(server.server_id)
        if expected_action != server.catalog_action or SIM_POOL_VERSION.get(server.server_id) != server.version:
            raise ValueError("unknown_or_tampered_otpcodesms_server")
        payload = self._fetch(server.catalog_action, {}, transport)
        if not isinstance(payload, list):
            self._raise_failure(server.catalog_action, payload)
        try:
            return tuple(
                OtpCodeSmsInventory(
                    server=server,
                    service=Service(
                        provider_service_id=str(item["id"]),
                        name=str(item["name"]),
                        price=str(item["price"]) if item.get("price") is not None else None,
                        available=(int(item["count"]) > 0) if item.get("count") is not None else None,
                        available_count=int(item["count"]) if item.get("count") is not None else None,
                    ),
                    country_id=str(item["country_id"]) if item.get("country_id") is not None else None,
                    service_code=str(item["service_code"]) if item.get("service_code") is not None else None,
                )
                for item in payload
            )
        except (KeyError, TypeError, ValueError) as exc:
            raise ProviderApiError("OTPCODESMS", server.catalog_action, OperationState.PROVIDER_ERROR) from exc

    def list_services(self, version: str = "v1", transport: JsonTransport | None = None) -> tuple[Service, ...]:
        """Compatibility view for old callers; new policy should use inventory."""
        server = self.get_server(f"SIM_{version.upper()}")
        if server is None:
            raise ValueError("only documented SIM v1 through v5 catalogs are supported")
        return tuple(item.service for item in self.list_inventory(server, transport))

    def resolve_service(self, name: str, version: str = "v2", transport: JsonTransport | None = None) -> Service | None:
        """Resolve only one exact provider label, leaving country choice to caller."""
        wanted = name.casefold().strip()
        matches = [item for item in self.list_services(version, transport) if item.name.casefold().strip() == wanted]
        return matches[0] if len(matches) == 1 else None

    def resolve_google_service(
        self,
        *,
        country_name: str = "Vietnam",
        transport: JsonTransport | None = None,
    ) -> Service | None:
        """Deprecated compatibility view; never select by largest inventory."""
        inventory = self.resolve_youtube_service(server="SIM_V3", country_name=country_name, transport=transport)
        return inventory.service if inventory else None

    def resolve_youtube_service(
        self,
        *,
        server: str | OtpCodeSmsServer,
        country_name: str = "Vietnam",
        transport: JsonTransport | None = None,
    ) -> OtpCodeSmsInventory | None:
        """Resolve a YouTube service within one exact server, not globally.

        Priority follows live provider semantics: exact `YouTube`, then a
        provider label carrying a standalone `youtube` token.  The requested
        country must be explicit in the same label.  Available candidates are
        ranked by lowest current price; a price tie fails closed rather than
        using stock size as an undocumented selector.
        """
        selected_server = self.get_server(server) if isinstance(server, str) else server
        if selected_server is None:
            return None
        wanted_country = set(re.findall(r"[a-z0-9]+", country_name.casefold()))
        exact, aliases = [], []
        for item in self.list_inventory(selected_server, transport):
            words = set(re.findall(r"[a-z0-9]+", item.service.name.casefold()))
            if not wanted_country.issubset(words) or item.service.available is not True:
                continue
            if item.service.name.casefold().strip() == "youtube":
                exact.append(item)
            elif "youtube" in words:
                aliases.append(item)
        candidates = exact or aliases
        if not candidates:
            return None
        def price(item: OtpCodeSmsInventory) -> int:
            try:
                return int(item.service.price or "")
            except ValueError:
                return 2**63 - 1
        lowest = min(price(item) for item in candidates)
        winners = [item for item in candidates if price(item) == lowest]
        return winners[0] if len(winners) == 1 else None

    def acquire_number(self, service: Service, *, version: str = "v2", transport: JsonTransport | None = None) -> NumberLease:
        action = {"v1": "get_number", "v2": "get_number_v2", "v3": "get_number_v3", "v4": "get_number_v4", "v5": "get_number_v5"}.get(version)
        if action is None:
            raise ValueError("only documented SIM v1 through v5 acquisition is supported")
        payload = self._fetch(action, {"id": service.provider_service_id}, transport)
        if not isinstance(payload, Mapping) or payload.get("success") is not True:
            self._raise_failure(action, payload)
        try:
            request_id = str(payload["request_id"])
            phone_number = str(payload["number"])
        except (KeyError, TypeError, ValueError) as exc:
            raise ProviderApiError("OTPCODESMS", action, OperationState.PROVIDER_ERROR) from exc
        if not request_id or not phone_number:
            raise ProviderApiError("OTPCODESMS", action, OperationState.PROVIDER_ERROR)
        return NumberLease(provider="OTPCODESMS", service=service, request_id=request_id, phone_number=phone_number)

    def acquire_inventory(self, inventory: OtpCodeSmsInventory, transport: JsonTransport | None = None) -> NumberLease:
        """Acquire against the exact server + service inventory resource."""
        return self.acquire_number(inventory.service, version=inventory.server.version, transport=transport)

    def get_order(self, order_id: str, *, version: str = "v2", transport: JsonTransport | None = None) -> OtpResult:
        # The acquisition catalog and the provider's underlying SIM source are
        # distinct observations.  A V2 catalog rental can identify a V4 poll
        # source, so polling supports every documented SIM code action while
        # acquisition itself remains limited to verified V1/V2 contracts.
        action = {
            "v1": "get_code",
            "v2": "get_code_v2",
            "v3": "get_code_v3",
            "v4": "get_code_v4",
            "v5": "get_code_v5",
        }.get(version)
        if action is None:
            raise ValueError("only documented SIM v1 through v5 OTP reads are supported")
        payload = self._fetch(action, {"id": order_id}, transport)
        if not isinstance(payload, Mapping):
            self._raise_failure(action, payload)
        status = str(payload.get("status", "")).casefold()
        if status in {"is_coming", "too_fast", "waiting"}:
            state = OperationState.WAITING_FOR_OTP
        elif status in {"timeout", "expired", "refunded"}:
            state = OperationState.EXPIRED
        elif payload.get("otp_code"):
            state = OperationState.OTP_RECEIVED
        else:
            self._raise_failure(action, payload)
            raise AssertionError("unreachable")
        # Some sources retain a terminal placeholder in `otp_code` after
        # expiry/refund.  It is never OTP material unless the normalized state
        # is explicitly OTP_RECEIVED.
        code = str(payload["otp_code"]) if state is OperationState.OTP_RECEIVED and payload.get("otp_code") is not None else None
        return OtpResult(
            provider="OTPCODESMS",
            request_id=order_id,
            state=state,
            code=code,
            can_request_more=bool(payload["can_request_more"]) if payload.get("can_request_more") is not None else None,
        )

    def wait_for_otp(self, order_id: str, *, version: str = "v2", transport: JsonTransport | None = None) -> OtpResult:
        return self.get_order(order_id, version=version, transport=transport)

    def wait_for_otp_auto(self, order_id: str, *, preferred_version: str = "v2", transport: JsonTransport | None = None) -> tuple[OtpResult, str]:
        """Read one order through its documented effective SIM source.

        A source mismatch has no side effect and is only used to discover the
        correct poll route for this already-created order.  Authentication,
        availability, and other errors are not retried here.
        """
        versions = tuple(dict.fromkeys((preferred_version, "v2", "v3", "v4", "v5", "v1")))
        last_error: ProviderApiError | None = None
        for version in versions:
            try:
                return self.get_order(order_id, version=version, transport=transport), version
            except ProviderApiError as error:
                if error.state is OperationState.INVALID_REQUEST:
                    last_error = error
                    continue
                raise
        if last_error is not None:
            raise last_error
        raise RuntimeError("no_documented_poll_route")

    def cancel_order(self, order_id: str, *, version: str = "v2", transport: JsonTransport | None = None) -> CancellationResult:
        action = {
            "v1": "cancel_phone",
            "v2": "cancel_phone_v2",
            "v3": "cancel_phone_v3",
            "v4": "cancel_phone_v4",
            "v5": "cancel_phone_v5",
        }.get(version)
        if action is None:
