    def _fetch(self, action: str, parameters: Mapping[str, str], transport: JsonTransport | None) -> object:
        if not self.api_key:
            raise ProviderApiError("OTPCODESMS", action, ProviderHealth.NOT_CONFIGURED)
        url = f"{API_BASE_URL}?{urlencode({'key': self.api_key, 'action': action, **parameters})}"
        try:
            return (transport or _read_json)(url)
        except ProviderApiError:
            raise
        except Exception as exc:  # do not include the key-bearing URL in a failure
            raise ProviderApiError("OTPCODESMS", action, ProviderHealth.UNAVAILABLE) from exc

    def _raise_failure(self, endpoint: str, payload: object) -> None:
        code = str(payload.get("code", "")) if isinstance(payload, Mapping) else ""
        message = str(payload.get("message", "")).casefold() if isinstance(payload, Mapping) else ""
        state = {
            "INSUFFICIENT_BALANCE": OperationState.INSUFFICIENT_BALANCE,
            "REQUEST_EXPIRED": OperationState.EXPIRED,
            "TOOL_PROCESSING": OperationState.RECONCILE_REQUIRED,
            "TOOL_FAILED": OperationState.NO_STOCK,
            "SOURCE_MISMATCH": OperationState.INVALID_REQUEST,
        }.get(code)
        if state is None:
            state = ProviderHealth.AUTH_FAILED if "invalid api key" in message else OperationState.PROVIDER_ERROR
        raise ProviderApiError("OTPCODESMS", endpoint, state)


def _read_json(url: str) -> object:
    request = Request(url, headers={"User-Agent": "Multiple-Automation-Capability-Validation/1.0", "Accept": "application/json"})
    with urlopen(request, timeout=30) as response:  # nosec B310 - exact authenticated official API base
        return json.loads(response.read().decode("utf-8"))


